-- Portable PostgreSQL schema (also runs on SQLite for local tests). IDs and timestamps are generated by the app.
CREATE TABLE IF NOT EXISTS admins (id UUID PRIMARY KEY, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, totp_secret_enc TEXT, totp_enabled BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS roles (id UUID PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS permissions (id UUID PRIMARY KEY, key TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS role_permissions (role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id UUID NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY (role_id, permission_id));
CREATE TABLE IF NOT EXISTS admin_role_assignments (admin_id UUID NOT NULL REFERENCES admins(id) ON DELETE CASCADE, role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY (admin_id, role_id));
CREATE TABLE IF NOT EXISTS sessions (id UUID PRIMARY KEY, admin_id UUID NOT NULL REFERENCES admins(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, ip_hash TEXT, user_agent TEXT, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS password_reset_requests (id UUID PRIMARY KEY, admin_id UUID NOT NULL REFERENCES admins(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY, admin_id UUID, action TEXT NOT NULL, entity TEXT, entity_id TEXT, ip_hash TEXT, details TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS security_events (id UUID PRIMARY KEY, type TEXT NOT NULL, email TEXT, ip_hash TEXT, details TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_security_events_lookup ON security_events (type, created_at);

CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS homepage_sections (id UUID PRIMARY KEY, key TEXT NOT NULL UNIQUE, title TEXT, body TEXT, data TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS biography (id UUID PRIMARY KEY, headline TEXT, body TEXT, photo_url TEXT, cv_url TEXT, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS services (id UUID PRIMARY KEY, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, summary TEXT, description TEXT, icon TEXT, price_note TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, summary TEXT, description TEXT, url TEXT, repo_url TEXT, category TEXT, tags TEXT, cover_url TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, is_featured BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS project_images (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, url TEXT NOT NULL, alt TEXT, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS skills (id UUID PRIMARY KEY, name TEXT NOT NULL, category TEXT, level INTEGER, sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS experience (id UUID PRIMARY KEY, role TEXT NOT NULL, organization TEXT, location TEXT, start_date TEXT, end_date TEXT, description TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS testimonials (id UUID PRIMARY KEY, author_name TEXT NOT NULL, author_role TEXT, quote TEXT NOT NULL, avatar_url TEXT, rating INTEGER, sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS social_links (id UUID PRIMARY KEY, platform TEXT NOT NULL, url TEXT NOT NULL, icon TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS navigation_items (id UUID PRIMARY KEY, label TEXT NOT NULL, url TEXT NOT NULL, location TEXT NOT NULL DEFAULT 'header', sort_order INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS content_revisions (id UUID PRIMARY KEY, entity TEXT NOT NULL, entity_id TEXT NOT NULL, snapshot TEXT NOT NULL, admin_id UUID, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_content_revisions_entity ON content_revisions (entity, entity_id, created_at);

CREATE TABLE IF NOT EXISTS article_categories (id UUID PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS article_tags (id UUID PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS articles (id UUID PRIMARY KEY, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, excerpt TEXT, content_md TEXT NOT NULL DEFAULT '', content_html TEXT NOT NULL DEFAULT '', featured_image_url TEXT, category_id UUID REFERENCES article_categories(id) ON DELETE SET NULL, seo_title TEXT, seo_description TEXT, canonical_url TEXT, author_id UUID REFERENCES admins(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','scheduled')), publish_at TIMESTAMPTZ, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_articles_status ON articles (status, published_at);
CREATE TABLE IF NOT EXISTS article_tag_assignments (article_id UUID NOT NULL REFERENCES articles(id) ON DELETE CASCADE, tag_id UUID NOT NULL REFERENCES article_tags(id) ON DELETE CASCADE, PRIMARY KEY (article_id, tag_id));
CREATE TABLE IF NOT EXISTS article_images (id UUID PRIMARY KEY, article_id UUID NOT NULL REFERENCES articles(id) ON DELETE CASCADE, url TEXT NOT NULL, alt TEXT, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS article_revisions (id UUID PRIMARY KEY, article_id UUID NOT NULL REFERENCES articles(id) ON DELETE CASCADE, title TEXT, content_md TEXT, saved_by UUID, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS article_comments (id UUID PRIMARY KEY, article_id UUID NOT NULL REFERENCES articles(id) ON DELETE CASCADE, author_name TEXT NOT NULL, author_email TEXT, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL);

CREATE TABLE IF NOT EXISTS media_folders (id UUID PRIMARY KEY, name TEXT NOT NULL, parent_id UUID REFERENCES media_folders(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS media_files (id UUID PRIMARY KEY, folder_id UUID REFERENCES media_folders(id) ON DELETE SET NULL, storage_provider TEXT NOT NULL, storage_key TEXT NOT NULL UNIQUE, url TEXT NOT NULL, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, width INTEGER, height INTEGER, checksum TEXT, alt_text TEXT, variants TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS media_metadata (media_id UUID NOT NULL REFERENCES media_files(id) ON DELETE CASCADE, key TEXT NOT NULL, value TEXT, PRIMARY KEY (media_id, key));
CREATE TABLE IF NOT EXISTS media_usage_references (id UUID PRIMARY KEY, media_id UUID NOT NULL REFERENCES media_files(id) ON DELETE CASCADE, entity TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_media_usage_entity ON media_usage_references (entity, entity_id);

CREATE TABLE IF NOT EXISTS contacts (id UUID PRIMARY KEY, name TEXT NOT NULL, email TEXT, phone TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_contacts_email ON contacts (email);
CREATE TABLE IF NOT EXISTS lead_sources (id UUID PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS leads (id UUID PRIMARY KEY, contact_id UUID NOT NULL REFERENCES contacts(id) ON DELETE CASCADE, source_id UUID REFERENCES lead_sources(id) ON DELETE SET NULL, service TEXT, budget TEXT, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','qualified','contacted','negotiating','converted','rejected','spam')), score INTEGER NOT NULL DEFAULT 0, qualification_reason TEXT, whatsapp_url TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, converted_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_leads_status ON leads (status, created_at);
CREATE TABLE IF NOT EXISTS lead_activities (id UUID PRIMARY KEY, lead_id UUID NOT NULL REFERENCES leads(id) ON DELETE CASCADE, type TEXT NOT NULL, note TEXT, admin_id UUID, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS conversations (id UUID PRIMARY KEY, contact_id UUID REFERENCES contacts(id) ON DELETE CASCADE, lead_id UUID REFERENCES leads(id) ON DELETE SET NULL, channel TEXT NOT NULL DEFAULT 'web', subject TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS contact_messages (id UUID PRIMARY KEY, contact_id UUID REFERENCES contacts(id) ON DELETE CASCADE, lead_id UUID REFERENCES leads(id) ON DELETE SET NULL, conversation_id UUID REFERENCES conversations(id) ON DELETE SET NULL, direction TEXT NOT NULL DEFAULT 'in', body TEXT NOT NULL, dedupe_hash TEXT, ip_hash TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_contact_messages_dedupe ON contact_messages (dedupe_hash, created_at);
CREATE TABLE IF NOT EXISTS follow_up_records (id UUID PRIMARY KEY, lead_id UUID NOT NULL REFERENCES leads(id) ON DELETE CASCADE, due_at TIMESTAMPTZ, note TEXT, done_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);

CREATE TABLE IF NOT EXISTS email_templates (id UUID PRIMARY KEY, name TEXT NOT NULL UNIQUE, subject TEXT NOT NULL, body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS email_contacts (id UUID PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS email_subscribers (id UUID PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT, status TEXT NOT NULL DEFAULT 'subscribed', unsubscribe_token TEXT NOT NULL, subscribed_at TIMESTAMPTZ NOT NULL, unsubscribed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS email_campaigns (id UUID PRIMARY KEY, name TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', sent_count INTEGER NOT NULL DEFAULT 0, failed_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL, sent_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS email_conversations (id UUID PRIMARY KEY, contact_email TEXT NOT NULL, subject TEXT, status TEXT NOT NULL DEFAULT 'open', lead_id UUID REFERENCES leads(id) ON DELETE SET NULL, last_message_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS email_messages (id UUID PRIMARY KEY, conversation_id UUID NOT NULL REFERENCES email_conversations(id) ON DELETE CASCADE, direction TEXT NOT NULL, from_email TEXT, to_email TEXT, subject TEXT, body TEXT NOT NULL, ai_classification TEXT, ai_summary TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS email_delivery_logs (id UUID PRIMARY KEY, to_email TEXT NOT NULL, subject TEXT, provider TEXT, provider_message_id TEXT, status TEXT NOT NULL, error TEXT, campaign_id UUID REFERENCES email_campaigns(id) ON DELETE SET NULL, conversation_id UUID, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS email_saved_replies (id UUID PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);

CREATE TABLE IF NOT EXISTS advertisers (id UUID PRIMARY KEY, name TEXT NOT NULL, contact_email TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS ad_placements (id UUID PRIMARY KEY, key TEXT NOT NULL UNIQUE, label TEXT NOT NULL, description TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS ad_campaigns (id UUID PRIMARY KEY, advertiser_id UUID REFERENCES advertisers(id) ON DELETE SET NULL, name TEXT NOT NULL, start_at TIMESTAMPTZ, end_at TIMESTAMPTZ, is_active BOOLEAN NOT NULL DEFAULT TRUE, notes TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS advertisements (id UUID PRIMARY KEY, campaign_id UUID REFERENCES ad_campaigns(id) ON DELETE SET NULL, advertiser_id UUID REFERENCES advertisers(id) ON DELETE SET NULL, title TEXT NOT NULL, image_url TEXT, alt TEXT, destination_url TEXT NOT NULL, placement_key TEXT NOT NULL, start_at TIMESTAMPTZ, end_at TIMESTAMPTZ, is_active BOOLEAN NOT NULL DEFAULT TRUE, weight INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS ad_impressions (ad_id UUID NOT NULL REFERENCES advertisements(id) ON DELETE CASCADE, day TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (ad_id, day));
CREATE TABLE IF NOT EXISTS ad_clicks (ad_id UUID NOT NULL REFERENCES advertisements(id) ON DELETE CASCADE, day TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (ad_id, day));
CREATE TABLE IF NOT EXISTS ad_network_settings (key TEXT PRIMARY KEY, value TEXT, enabled BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMPTZ NOT NULL);

CREATE TABLE IF NOT EXISTS analytics_events (id UUID PRIMARY KEY, type TEXT NOT NULL, path TEXT, ref_id TEXT, day TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_analytics_events_day ON analytics_events (type, day);
CREATE TABLE IF NOT EXISTS page_views (id UUID PRIMARY KEY, path TEXT NOT NULL, visitor_hash TEXT NOT NULL, referrer_host TEXT, day TEXT NOT NULL, is_test BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_page_views_day ON page_views (day);
CREATE TABLE IF NOT EXISTS project_views (slug TEXT NOT NULL, day TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (slug, day));
CREATE TABLE IF NOT EXISTS article_views (article_id UUID NOT NULL REFERENCES articles(id) ON DELETE CASCADE, day TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (article_id, day));
CREATE TABLE IF NOT EXISTS conversion_events (id UUID PRIMARY KEY, type TEXT NOT NULL, ref_id TEXT, day TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS traffic_sources (source TEXT NOT NULL, day TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (source, day));

CREATE TABLE IF NOT EXISTS system_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS backup_history (id UUID PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL, size_bytes INTEGER, location TEXT, checksum TEXT, verified_at TIMESTAMPTZ, notes TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS application_logs (id UUID PRIMARY KEY, level TEXT NOT NULL, message TEXT NOT NULL, context TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS notification_settings (key TEXT PRIMARY KEY, value TEXT, enabled BOOLEAN NOT NULL DEFAULT TRUE);
